    /// Federation directory: write a revocation.
    fn put_revocation(&self, py: Python<'_>, signed_revocation_json: &str) -> PyResult<()> {
        self.ensure_usable()?;
        catch_panic(|| {
            let runtime = self.runtime.clone();
            let rev: crate::federation::SignedRevocation =
                serde_json::from_str(signed_revocation_json).map_err(|e| {
                    PyValueError::new_err(format!("SignedRevocation JSON decode: {e}"))
                })?;

            // v0.3.1 — cold-path PQC fill-in (CIRISPersist#10).
            let cold_path_inputs =
                self.local_signer
                    .as_ref()
                    .and_then(|s| s.pqc_signer())
                    .map(|signer| {
                        (
                            signer,
                            rev.revocation.revocation_id.clone(),
                            rev.revocation.revocation_envelope.clone(),
                            rev.revocation.scrub_signature_classical.clone(),
                        )
                    });

            py.detach(|| match &self.backend {
                BackendDispatch::Postgres(pg) => {
                    let backend = pg.clone();
                    runtime.block_on(async move {
                        use crate::federation::FederationDirectory;
                        backend
                            .put_revocation(rev)
                            .await
                            .map_err(federation_err_to_py)?;
                        if let Some((signer, revocation_id, envelope, classical_sig_b64)) =
                            cold_path_inputs
                        {
                            let backend = backend.clone();
                            tokio::spawn(async move {
                                match cold_path_pqc_sign(&*signer, &envelope, &classical_sig_b64)
                                    .await
                                {
                                    Ok((_pubkey_b64, pqc_sig_b64)) => {
                                        if let Err(e) = backend
                                            .attach_revocation_pqc_signature(
                                                &revocation_id,
                                                &pqc_sig_b64,
                                            )
                                            .await
                                        {
                                            tracing::warn!(
                                                revocation_id = revocation_id.as_str(),
                                                error = %e,
                                                "cold-path PQC \
                                                 attach_revocation_pqc_signature failed; \
                                                 row stays hybrid-pending"
                                            );
                                        }
                                    }
                                    Err(e) => {
                                        tracing::warn!(
                                            revocation_id = revocation_id.as_str(),
                                            error = %e,
                                            "cold-path PQC sign failed; row stays hybrid-pending"
                                        );
                                    }
                                }
                            });
                        }
                        Ok(())
                    })
                }
                #[cfg(feature = "sqlite")]
                BackendDispatch::Sqlite(sq) => {
                    let backend = sq.clone();
                    runtime.block_on(async move {
                        use crate::federation::FederationDirectory;
                        backend
                            .put_revocation(rev)
                            .await
                            .map_err(federation_err_to_py)?;
                        if let Some((signer, revocation_id, envelope, classical_sig_b64)) =
                            cold_path_inputs
                        {
                            let backend = backend.clone();
                            tokio::spawn(async move {
                                match cold_path_pqc_sign(&*signer, &envelope, &classical_sig_b64)
                                    .await
                                {
                                    Ok((_pubkey_b64, pqc_sig_b64)) => {
                                        if let Err(e) = backend
                                            .attach_revocation_pqc_signature(
                                                &revocation_id,
                                                &pqc_sig_b64,
                                            )
                                            .await
                                        {
                                            tracing::warn!(
                                                revocation_id = revocation_id.as_str(),
                                                error = %e,
                                                "cold-path PQC \
                                                 attach_revocation_pqc_signature failed; \
                                                 row stays hybrid-pending"
                                            );
                                        }
                                    }
                                    Err(e) => {
                                        tracing::warn!(
                                            revocation_id = revocation_id.as_str(),
                                            error = %e,
                                            "cold-path PQC sign failed; row stays hybrid-pending"
                                        );
                                    }
                                }
                            });
                        }
                        Ok(())
                    })
                }
            })
        })
    }

    /// v8.8.0 (CIRISPersist#234, CEG 1.0-RC28/RC29 §5.6.8.15) — the
    /// symmetric **deregister** path over FFI. JSON-over-FFI mirror of
    /// [`Engine::deregister_federation_key`](crate::engine::Engine::deregister_federation_key):
    /// the revocation teeth a withdrawn `consent:replication` relies
    /// on. Thin alias over the existing `put_revocation` store path
    /// (same `SignedRevocation` JSON shape, same trust / region /
    /// anti-rollback gates); composing the existing revocation
    /// substrate rather than inventing a parallel one. A consumer then
    /// ceases admitting the deregistered peer's rows on read.
    fn deregister_federation_key(
        &self,
        py: Python<'_>,
        signed_revocation_json: &str,
    ) -> PyResult<()> {
        self.put_revocation(py, signed_revocation_json)
    }

