    /// Federation blob storage: read a blob by SHA-256 (hex).
    ///
    /// Returns `None` when no row exists; otherwise a JSON string of
    /// `BlobBody`:
    ///
    /// - Inline: `{"inline": "<base64-bytes>"}`
    /// - External: `{"external": {"uri": "...", "size_bytes": N,
    ///   "media_type": "...|null"}}`
    fn get_blob_json(&self, py: Python<'_>, sha256_hex: &str) -> PyResult<Option<String>> {
        self.ensure_usable()?;
        catch_panic(|| {
            let runtime = self.runtime.clone();
            let sha = parse_sha256_hex(sha256_hex)?;
            py.detach(move || match &self.backend {
                BackendDispatch::Postgres(pg) => {
                    let backend = pg.clone();
                    runtime.block_on(async move {
                        use crate::federation::BlobStorage;
                        let body_opt = backend.get_blob(&sha).await.map_err(blob_err_to_py)?;
                        match body_opt {
                            None => Ok(None),
                            Some(body) => encode_blob_body_json(&body).map(Some),
                        }
                    })
                }
                #[cfg(feature = "sqlite")]
                BackendDispatch::Sqlite(sq) => {
                    let backend = sq.clone();
                    runtime.block_on(async move {
                        use crate::federation::BlobStorage;
                        let body_opt = backend.get_blob(&sha).await.map_err(blob_err_to_py)?;
                        match body_opt {
                            None => Ok(None),
                            Some(body) => encode_blob_body_json(&body).map(Some),
                        }
                    })
                }
            })
        })
    }

    /// v6.8.0 (CIRISPersist#149) — serve blob bytes to a federation
    /// PEER, with the proactive disk-pressure gate on the proxy-SERVE
    /// path. At the stop tier (or tighter) refuses to SERVE
    /// federation-proxied content (blob with no local/family holder),
    /// raising `ValueError` (`blob_disk_pressure_proxy_refused`, a
    /// Permanent signal — the peer should fetch from another holder),
    /// while still serving local + family content. Raises `ValueError`
    /// (`blob_not_held`) when the blob is absent. Returns the blob body
    /// as the same JSON shape as `get_blob_json`.
    fn serve_blob_to_peer_json(
        &self,
        py: Python<'_>,
        sha256_hex: &str,
        requesting_peer_key_id: &str,
    ) -> PyResult<String> {
        self.ensure_usable()?;
        catch_panic(|| {
            let runtime = self.runtime.clone();
            let sha = parse_sha256_hex(sha256_hex)?;
            let peer = requesting_peer_key_id.to_owned();
            let slot = engine_slot();
            let cell = slot
                .as_ref()
                .ok_or_else(|| PyRuntimeError::new_err("engine cell missing"))?;
            let engine = cell.engine_view();
            drop(slot);
            py.detach(move || {
                runtime.block_on(async move {
                    let body = engine
                        .serve_blob_to_peer(&sha, &peer)
                        .await
                        .map_err(blob_err_to_py)?;
                    encode_blob_body_json(&body)
                })
            })
        })
    }

    /// v4.1 (CIRISPersist#142, Cut A) — byte-range read over a blob by
    /// SHA-256 (hex). RFC 9110 §14.4 semantics: `end_inclusive` is
    /// clamped to size-1; a `start` at/past the blob size raises
    /// `ValueError` (RangeNotSatisfiable); `start > end_inclusive` raises
    /// `ValueError` (InvalidArgument); an absent blob returns `None`.
    ///
    /// Result shape:
    /// - Inline blob → the requested bytes as `bytes`.
    /// - External blob → a dict `{"external_uri": str, "range_start":
    ///   int, "range_end_inclusive": int}` — persist does NOT
    ///   dereference; the caller fetches that range from the URI itself.
    fn get_blob_range(
        &self,
        py: Python<'_>,
        sha256_hex: &str,
        start: u64,
        end_inclusive: u64,
    ) -> PyResult<Option<Py<PyAny>>> {
        self.ensure_usable()?;
        catch_panic(|| {
            let runtime = self.runtime.clone();
            let sha = parse_sha256_hex(sha256_hex)?;
            let range_opt = py.detach(move || match &self.backend {
                BackendDispatch::Postgres(pg) => {
                    let backend = pg.clone();
                    runtime.block_on(async move {
                        use crate::federation::BlobStorage;
                        backend
                            .get_blob_range(&sha, start, end_inclusive)
                            .await
                            .map_err(blob_err_to_py)
                    })
                }
                #[cfg(feature = "sqlite")]
                BackendDispatch::Sqlite(sq) => {
                    let backend = sq.clone();
                    runtime.block_on(async move {
                        use crate::federation::BlobStorage;
                        backend
                            .get_blob_range(&sha, start, end_inclusive)
                            .await
                            .map_err(blob_err_to_py)
                    })
                }
            })?;
            match range_opt {
                None => Ok(None),
                Some(crate::federation::BlobRange::Inline(bytes)) => {
                    Ok(Some(PyBytes::new(py, &bytes).into_any().unbind()))
                }
                Some(crate::federation::BlobRange::External {
                    external_ref,
                    range_start,
                    range_end_inclusive,
                }) => {
                    let dict = PyDict::new(py);
                    dict.set_item("external_uri", external_ref.uri)?;
                    dict.set_item("range_start", range_start)?;
                    dict.set_item("range_end_inclusive", range_end_inclusive)?;
                    Ok(Some(dict.into_any().unbind()))
                }
            }
        })
    }

    /// v9.1.0 (CC 1.13.3 / FSD §2.4, CIRISPersist#243; FFI #271) — admit
    /// one caller-pre-encrypted (XChaCha20-Poly1305) RaptorQ symbol into
    /// the scope-blob store, addressed by `(record_id, symbol_index)`.
    ///
    /// Persist NEVER encrypts/decrypts; it stores the opaque seal
    /// components verbatim. Mirrors
    /// [`BlobStorage::put_scope_blob`](crate::federation::BlobStorage::put_scope_blob)
    /// — see that method for the first-write-wins idempotency contract
    /// (re-put of an existing `(record_id, symbol_index)` is a no-op) and
    /// the opaque-holder property (only the DEK *epoch* is persisted).
    ///
    /// Parameters (all byte params are `bytes`):
    /// - `record_id` — the FSD §2.4 HMAC-SHA3-256 output (32 bytes).
    /// - `symbol_index` — `0..N` symbol index within the record.
    /// - `nonce` — XChaCha20-Poly1305 nonce (24 bytes).
    /// - `ciphertext` — the pre-encrypted symbol bytes (opaque).
    /// - `tag` — Poly1305 tag (16 bytes).
    /// - `group_dek_ref_json` — JSON object
    ///   `{"community_key_id": str, "epoch": int}` tying the symbol to the
    ///   community DEK epoch it was sealed under (a
    ///   [`GroupDekRef`](crate::federation::GroupDekRef)).
    #[allow(clippy::too_many_arguments)]
    fn put_scope_blob(
        &self,
        py: Python<'_>,
        record_id: &Bound<'_, PyBytes>,
        symbol_index: u16,
        nonce: &Bound<'_, PyBytes>,
        ciphertext: &Bound<'_, PyBytes>,
        tag: &Bound<'_, PyBytes>,
        group_dek_ref_json: &str,
    ) -> PyResult<()> {
        self.ensure_usable()?;
        catch_panic(|| {
            let runtime = self.runtime.clone();
            let record_id = parse_fixed_bytes::<32>(record_id, "record_id")?;
            let nonce = parse_fixed_bytes::<24>(nonce, "nonce")?;
            let tag = parse_fixed_bytes::<16>(tag, "tag")?;
            let ciphertext = ciphertext.as_bytes().to_vec();
            let group_dek_ref: crate::federation::GroupDekRef =
                serde_json::from_str(group_dek_ref_json).map_err(|e| {
                    PyValueError::new_err(format!(
                        "group_dek_ref must be JSON {{\"community_key_id\": str, \
                         \"epoch\": int}}: {e}"
                    ))
                })?;
            py.detach(move || match &self.backend {
                BackendDispatch::Postgres(pg) => {
                    let backend = pg.clone();
                    runtime.block_on(async move {
                        use crate::federation::BlobStorage;
                        backend
                            .put_scope_blob(
                                record_id,
                                symbol_index,
                                nonce,
                                ciphertext,
                                tag,
                                group_dek_ref,
                            )
                            .await
                            .map_err(blob_err_to_py)
                    })
                }
                #[cfg(feature = "sqlite")]
                BackendDispatch::Sqlite(sq) => {
                    let backend = sq.clone();
                    runtime.block_on(async move {
                        use crate::federation::BlobStorage;
                        backend
                            .put_scope_blob(
                                record_id,
                                symbol_index,
                                nonce,
                                ciphertext,
                                tag,
                                group_dek_ref,
                            )
                            .await
                            .map_err(blob_err_to_py)
                    })
                }
            })
        })
    }

    /// v9.1.0 (FSD §2.4, CIRISPersist#243; FFI #271) — read one scope-blob
    /// symbol back by `(record_id, symbol_index)`. Returns `None` if
    /// absent; otherwise a `(nonce, ciphertext, tag)` tuple of `bytes`.
    ///
    /// Bumps the row's `last_accessed_at` (the LRU signal the capacity
    /// sweeper consumes). The bytes round-trip exactly what
    /// [`put_scope_blob`](Self::put_scope_blob) admitted — persist never
    /// decrypts. Mirrors
    /// [`BlobStorage::get_scope_blob`](crate::federation::BlobStorage::get_scope_blob).
    fn get_scope_blob<'py>(
        &self,
        py: Python<'py>,
        record_id: &Bound<'py, PyBytes>,
        symbol_index: u16,
    ) -> PyResult<Option<Py<PyAny>>> {
        self.ensure_usable()?;
        catch_panic(|| {
            let runtime = self.runtime.clone();
            let record_id = parse_fixed_bytes::<32>(record_id, "record_id")?;
            let sym_opt = py.detach(move || match &self.backend {
                BackendDispatch::Postgres(pg) => {
                    let backend = pg.clone();
                    runtime.block_on(async move {
                        use crate::federation::BlobStorage;
                        backend
                            .get_scope_blob(record_id, symbol_index)
                            .await
                            .map_err(blob_err_to_py)
                    })
                }
                #[cfg(feature = "sqlite")]
                BackendDispatch::Sqlite(sq) => {
                    let backend = sq.clone();
                    runtime.block_on(async move {
                        use crate::federation::BlobStorage;
                        backend
                            .get_scope_blob(record_id, symbol_index)
                            .await
                            .map_err(blob_err_to_py)
                    })
                }
            })?;
            match sym_opt {
                None => Ok(None),
                Some(sym) => {
                    let tuple = pyo3::types::PyTuple::new(
                        py,
                        [
                            PyBytes::new(py, &sym.nonce).into_any(),
                            PyBytes::new(py, &sym.ciphertext).into_any(),
                            PyBytes::new(py, &sym.tag).into_any(),
                        ],
                    )?;
                    Ok(Some(tuple.into_any().unbind()))
                }
            }
        })
    }

